use crate::common;
use rust_xlsxwriter::{
    ConditionalFormatText, ConditionalFormatTextRule, Format, Workbook, XlsxError,
};

// Test text rules with double quotes and non-ASCII strings.
fn create_new_xlsx_file(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    worksheet.write(0, 0, r#"say "hi""#)?;
    worksheet.write(1, 0, "café")?;
    worksheet.write(2, 0, "a😀")?;
    worksheet.write(3, 0, "other")?;

    let format = Format::new().set_background_color("FFFF00");

    let conditional_format = ConditionalFormatText::new()
        .set_rule(ConditionalFormatTextRule::Contains(
            r#"say "hi""#.to_string(),
        ))
        .set_format(&format);

    worksheet.add_conditional_format(0, 0, 3, 0, &conditional_format)?;

    let conditional_format = ConditionalFormatText::new()
        .set_rule(ConditionalFormatTextRule::BeginsWith("café".to_string()))
        .set_format(&format);

    worksheet.add_conditional_format(0, 0, 3, 0, &conditional_format)?;

    let conditional_format = ConditionalFormatText::new()
        .set_rule(ConditionalFormatTextRule::EndsWith("a😀".to_string()))
        .set_format(&format);

    worksheet.add_conditional_format(0, 0, 3, 0, &conditional_format)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_cond_format25() {
    let test_runner = common::TestRunner::new()
        .set_name("cond_format25")
        .set_function(create_new_xlsx_file)
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
